@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix sosa: <http://www.w3.org/ns/sosa/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/data/Observation_235754> ;
            sh:resultMessage "sosa:observedProperty is required, on the observation or a collection it is a member of" ;
            sh:resultPath sosa:observedProperty ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "sosa:observedProperty is required, on the observation or a collection it is a member of" ;
                    sh:select """
            PREFIX sosa: <http://www.w3.org/ns/sosa/>
            PREFIX geojson: <https://purl.org/geojson/vocab#>
            SELECT $this (sosa:observedProperty AS ?path) WHERE {
                FILTER NOT EXISTS {
                    $this (^sosa:hasMember|^geojson:features|sosa:memberOf)* ?holder .
                    ?holder sosa:observedProperty ?prop .
                }
                FILTER (EXISTS { $this a sosa:Observation } || NOT EXISTS {
                    { $this a ?type . FILTER(?type IN (sosa:Actuation, sosa:Sampling)) }
                    UNION
                    { $this sosa:actsOnProperty|sosa:madeByActuator|sosa:madeBySampler ?x }
                    UNION
                    {
                        $this (^sosa:hasMember|^geojson:features|sosa:memberOf)+ ?collection .
                        ?collection a ?ctype .
                        FILTER(?ctype IN (sosa:ActuationCollection, sosa:SamplingCollection))
                    }
                })
            }
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://www.ogc.org/rules/sosa/#testObservedPropertyPresent> ;
            sh:value <https://example.org/data/Observation_235754> ] .

